-- Upsert aptis_content_blocks
INSERT INTO public.aptis_content_blocks (skill, block_type, source_key, title, content, media_url, metadata, content_hash)
VALUES
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-fashion-club-p4-instructions', 'Club Notice for Fashion Club', 'Dear members, The Fashion Club is planning an event with famous designers who will discuss their work and answer members’ questions. Some members prefer an online meeting because it would be convenient and inexpensive, while others want a live fashion-show-style event. Please tell us which format you prefer, explain your reasons, and suggest how the event should be organised.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'a249cad5137f542c7d02897c043ea15fc760abc03a7c1d937128e06f18862645'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-social-club-p4-instructions', 'Club Notice for Social Club', 'Dear members, The Social Club is planning an event to help people meet others and make new friends. We are considering two formats: an online event that is easy to join from home, or an in-person event with face-to-face activities. Please tell us which option you prefer, how you feel about the plan, and what activities should be included.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'fd242f64244376fb122894fced3c3c91c412e1249505faaa6dde32e690fa7bac'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-television-club-p4-instructions', 'Club Notice for Television Club', 'Dear members, The Television Club is planning its first face-to-face international conference. Many members come from different countries and have only communicated online, so this will be an opportunity for everyone to meet in person. Please suggest a suitable venue and activities that could help members get to know one another, exchange ideas, and enjoy the event.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '466123a1b280a3232d305e9a38419c424e377044dcd85527b6e4e56b0936b246'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-book-club-p4-instructions', 'Club Notice for Book Club', 'Dear members, From next month, the Book Club will no longer be able to provide members with one free book each month. In addition, problems with our delivery service mean that orders may take four to six weeks to arrive. We apologise for these changes and would like to hear your reactions, suggestions for improving the service, and ideas for alternative member benefits.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'afda376d0b811ff7b2c13321b40e78b5c41c9368091274778fbe31b8574e8231'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-art-club-p4-instructions', 'Club Notice for Art Club', 'Dear members, The Art Club is planning a public talk to attract more interest in our activities and encourage both younger and older people to join. We would like to invite a well-known artist, but we have not yet chosen the speaker or the topic. Please recommend a suitable artist, suggest an engaging subject, and explain how the event could appeal to different age groups.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '856cfad2354164d8be8a63336b27c7db66199d4ffc6cb4044064e9377d997a11'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-language-club-version-1-p4-instructions', 'Club Notice for Language Club (Version 1)', 'Dear members, You have been studying English at the American Dream Center for two months and have found the course effective, practical, and enjoyable. You would like to recommend it to a friend. However, you have also registered for the next course but can no longer attend because your personal schedule has changed. Please explain the situation and suggest a suitable solution.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '5996f476e4c58029a2fd59858f158632e20ce964b823a521d34fdaf6f1e200a9'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-technology-club-p4-instructions', 'Club Notice for Technology Club', 'Dear members, Our website is an important place for members to share ideas, but recently some comments have been rude or negative. The club is considering changing the website so that every comment shows the writer’s real identity. Please give your opinion on this proposal and suggest other ways to encourage respectful discussion while protecting members’ privacy.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '2a3e23d4bf94928d8d3738ee56ba80002be1053a2419337e9b3d65206dbc1e68'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-debate-club-p4-instructions', 'Club Notice for Debate Club', 'Dear members, The Debate Club is preparing a campaign to attract new members. We want to explain how learning to debate and speak in public can be useful in education, work, and everyday life. Please identify two important benefits, give examples of how these skills help people, and suggest an activity that could introduce beginners to the club.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'b6e7b3e12dc3f4bf74531918f9ac982fd36e2db7f9f9442e3493d79f04d7a2c7'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-english-club-version-3-p4-instructions', 'Club Notice for English Club (Version 3)', 'Dear members, We are sorry to announce that this week’s English Club talk show has been cancelled because the invited guests are unexpectedly unavailable. As we do not currently have a backup plan, there will be no regular meeting this week. Please tell us how you feel and suggest an alternative activity, replacement speaker, or online event that could be arranged instead.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'ecf739c0d45b1cfc4b5cd38487e2bb78d9f4bb61f7e446590c8a44fffd1084fe'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-fitness-club-p4-instructions', 'Club Notice for Fitness Club', 'Dear members, Some of the Fitness Club’s equipment is old and needs to be replaced. One proposal is to hold a sponsorship event to raise money for new equipment. Another suggestion is to increase the membership fee by 50 percent. Please tell us which option you prefer, explain your reasons, and suggest any other practical ways to fund the improvements.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '06ca33615bc150a483bd5b3dbd169e6dd034dc037246be077be14152b7f8cea0'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-photography-club-p4-instructions', 'Club Notice for Photography Club', 'Dear members, The Photography Club is preparing an exhibition featuring the best photographs taken by club members. We want the exhibition to be interesting and accessible to visitors of all ages, from children to older adults. Please suggest suitable themes, ways to display the photographs, and activities that could help different age groups enjoy and understand the exhibition.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '00fd446e5f06d7922244412a57d6e5b4e8baf865053b12096c4580798e694616'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-reading-club-p4-instructions', 'Club Notice for Reading Club', 'Dear members, The Reading Club has been invited to contribute ideas for a new community library. The organisers want the building to appeal to both younger and older readers and to provide more than just shelves of books. Please suggest useful facilities, comfortable reading areas, technology, events, or services that would make the library welcoming and practical for everyone.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'b85bb3c81d3f86f821baccde7a5d8b42d9edb626fb10ee13b4ef0acef6f87bb6'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-sports-club-p4-instructions', 'Club Notice for Sports Club', 'Dear members, The Sports Club plans to organise a competition for younger members. We want the event to be exciting, inclusive, and safe for participants with different abilities and levels of experience. Please suggest suitable sports, age categories, team arrangements, prizes, and safety measures. We would also like ideas for encouraging more young people to take part.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '2b6209e354d13003486ba1d0ec6daeca2bf4dacc7bb6f31f37b5ad4382bbc544'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-food-club-p4-instructions', 'Club Notice for Food Club', 'Dear members, The Food Club is planning a special meeting with a well-known chef, and we hope to attract a large audience. The chef will give a talk and demonstrate how to prepare a meal. Please suggest an interesting topic for the talk, a suitable dish for the demonstration, and any additional activities that could make the event more enjoyable.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '7a41ba4cfe1525095e5bbead85d4ee160dd56a13769594a3b011a558a8a00bb5'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-english-club-version-1-p4-instructions', 'Club Notice for English Club (Version 1)', 'Dear members, New words and expressions are constantly entering the English language, especially through social media, technology, and popular culture. Some people welcome these changes because they make language more creative and modern, while others believe that language should follow clear rules. We would like to hear your views and the reasons why this issue causes such strong reactions.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'b1a4b4fa7128d466978fb6f32819a0b6a6abea76c4c6b3771dcad94c3d926fcc'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-outdoor-club-p4-instructions', 'Club Notice for Outdoor Club', 'Dear members, The Outdoor Club is planning a summer trip and must choose between the mountains and the coast. We want the trip to be enjoyable, safe, and suitable for both younger and older members. Please tell us which destination you prefer and suggest activities, transport, accommodation, or facilities that would meet the needs of different age groups.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '0c9315b2951811d6db6b6f915409c38ef5fcf77061a109a3b1ea2951cea6a001'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-english-club-version-2-p4-instructions', 'Club Notice for English Club (Version 2)', 'Dear members, The English Club is planning a public talk to attract new members from different age groups. We want the event to be useful and enjoyable for both younger and older learners. Please suggest a suitable speaker, an interesting topic, and activities that would encourage audience participation. We would also like ideas for promoting the event effectively.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '4648840fa8eb60c53502e4c1cab560c15f20f7db67682dbd88cb1d40458dd7ea'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-museum-club-p4-instructions', 'Club Notice for Museum Club', 'Dear members, The Museum Club is considering introducing an entrance fee for members when they visit the museum. The money would help cover rising costs and support new exhibitions, but some members believe visits should remain free. Please give your opinion, suggest a reasonable pricing policy, and explain whether discounts or free-entry days should be offered.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'a20d54f280b1bae4bcc43d9efff4f3c9440b6f24094f4b3bdde0e277f64207ba'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-home-living-club-p4-instructions', 'Club Notice for Home Living Club', 'Dear members, Many young families would like to buy a house or apartment, but they often find the process expensive, confusing, and stressful. The Home Living Club wants to offer useful support. Please suggest how families can search for suitable homes, compare prices, understand legal and financial matters, and avoid common mistakes when making such an important decision.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '8a01e65102c6d56d9fde72f18b20d422b69df29b658b361996b917836bad430c'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-business-club-p4-instructions', 'Club Notice for Business Club', 'Dear members, The Business Club wants to support local people who are planning to start small businesses. We are considering two proposals: creating a call centre where people can ask questions and receive advice, or offering free business courses in partnership with nearby universities. Please tell us which option would be more useful, explain why, and suggest how it could operate successfully.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'ba45830edbec758c363ccdc9ce67b43620efa5e2fc645b251f98f1f8aa32a82c'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-film-club-p4-instructions', 'Club Notice for Film Club', 'Dear members, Unfortunately, actor James McAvoy cannot give the planned talk at our next meeting for personal reasons. He has offered to return next year, either in January or March. The meeting will still take place, with a discussion about the advantages and disadvantages of learning online. Please tell us your preferred month and suggest any other suitable activities or replacement speakers.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '30c3cc086f97b70e7015ea26df5411a56c6eaadc574e473ca0bd3044fd463eed'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-travel-club-version-2-p4-instructions', 'Club Notice for Travel Club (Version 2)', 'Dear members, The Travel Club wants to help people who are travelling abroad for the first time. New travellers may worry about planning, transport, money, safety, and communicating in another language. Please suggest practical advice or services the club could provide, and recommend the easiest ways for travellers to communicate with local people while they are overseas.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '806541d114afee5b22556ea4df8505ce87a55ed15fa4db900101ed663c6efb6e'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-cinema-club-p4-instructions', 'Club Notice for Cinema Club', 'Dear members, Our weekly film screenings are very popular, but we have received several complaints about people using mobile phones during the films. Reminding audiences to switch off their phones has not solved the problem, so the club is considering a complete ban inside the cinema. Please give your opinion on the ban and suggest other fair and practical solutions.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '56180fa2639fbfb41b0af4d919f46cc89635d115a7a47deac8170c415e7073c0'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-science-club-p4-instructions', 'Club Notice for Science Club', 'Dear members, The Science Club is organising an exhibition next month for both young people and older visitors. We need ideas for interactive displays, demonstrations, talks, and activities that everyone can enjoy. We are also considering whether visitors should buy tickets. Please suggest suitable attractions and tell us whether admission should be free, paid, or discounted for certain groups.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'c1f27e7f2a4d17681f40aa0065ce2f525d7085d807cd8bfdde5170715bde7421'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-computer-club-p4-instructions', 'Club Notice for Computer Club', 'Dear members, The Computer Club plans to redesign its website because the current version looks outdated and is not attracting enough new members. We would like the new site to be clear, modern, and easy to use on both computers and mobile phones. Please share your feelings about the plan and suggest useful content, features, or design improvements.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'af71640802dec8fee934893be67e41c3948e8fffcff37441c1d9e54242c83a93'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-garden-club-p4-instructions', 'Club Notice for Garden Club', 'Dear members, The talk and slide show on “The Gardens of Japan” has been cancelled because Mr Seiko is unwell. Mr Jones has kindly offered to repeat his talk on “The Gardens of England”, although many members have already heard it. Please tell us how you feel about this change and suggest alternative speakers, topics, or activities for the meeting.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '16046f670adaefc3c695a4ab341dac29418ea39fac382174443d6ac399dece41'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-healthy-club-p4-instructions', 'Club Notice for Healthy Club', 'Dear members, For personal reasons, our instructor will be away for the next two weeks. During this period, members may use the club’s facilities, but there will be no professional supervision or organised classes. We apologise for the inconvenience and are concerned about safety. Please share your views and suggest suitable temporary arrangements or alternative activities.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '12841da08001ba0833afe1d280721ba7d95c36c8e3164c84fcfbeac62b953eb1'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-english-club-version-2-set002-p4-instructions', 'Club Notice for English Club (Version 2)', 'Dear Members, We are sorry to inform you that the Talk show has been canceled as the guests are unexpectedly busy. We do not have any back-up plan, so there will be no meeting this week. We will inform you of the reopening of the Talk show as soon as we can. We are sorry for the inconvenience.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'c1e634fa48b9e13d305f0dc372eed989fd5285ffebcca2677f2d961e87c6a6a8'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-writing-club-p4-instructions', 'Club Notice for Writing Club', 'Dear members, Many members have complained that the Writing Club website looks unprofessional and is difficult to navigate. Important information is hard to find, and some pages do not work well on mobile phones. We plan to improve the site and would like your suggestions about its layout, content, writing resources, interactive features, and overall ease of use.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '215813b39a2ff78d154b02ceb2d51d2c2a5d30bde6238da0bc7ef1b85aee14c2'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-nature-club-p4-instructions', 'Club Notice for Nature Club', 'Dear members, Many young people spend most of their free time at home playing computer games or using their phones. The Nature Club would like to create a programme that encourages them to spend more time outdoors and learn about the natural world. Please suggest enjoyable activities, suitable locations, and effective ways to attract young participants.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'c88a2d8be667294c4853567e9fb9f90c037973b301baac0e3ab3a23d33c91411'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-language-club-version-2-p4-instructions', 'Club Notice for Language Club (Version 2)', 'Dear members, The Language Club will hold a lecture about language learning next month. We are looking for a club member to be the guest speaker and would like the talk to be practical, interesting, and useful for learners at different levels. Members who wish to speak should explain why they are suitable and propose a clear topic for the lecture.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '7129c2a2100e83aabc4250c5090e62b796df60c01b95ea10ab0f38e5269f8a0d'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-community-club-p4-instructions', 'Club Notice for Community Club', 'Dear members, Our Community Club needs more support this year. We are looking for members who can take an active role in current projects, as well as creative ideas for new activities that benefit local people. Please suggest ways to recruit and motivate volunteers, and recommend one or two practical projects that the club could organise in the coming months.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '9bac9a2e1a62007164b6d2b5ffc0168f38f8749232601ae551756cd51a2ed11b'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-home-living-p4-instructions', 'Club Notice for Home Living', 'Dear members, Many young families would like to buy a house or apartment, but they often find the process expensive, confusing, and stressful. The Home Living Club wants to offer useful support. Please suggest how families can search for suitable homes, compare prices, understand legal and financial matters, and avoid common mistakes when making such an important decision.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '8a01e65102c6d56d9fde72f18b20d422b69df29b658b361996b917836bad430c'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-walking-club-version-1-p4-instructions', 'Club Notice for Walking Club (Version 1)', 'Dear members, The Walking Club is considering a two-week walking tour through several European countries. Some members are excited about the opportunity, while others are worried about the cost, distance, fitness level, and amount of time required. Please share your opinion and suggest ways to make the tour safer, more affordable, and suitable for a wider range of members.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '52752d2d1d4cd53a3b09a3aa0538a3b900e822e710c8d889fefe1a1cc994ebb3'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-beautiful-homes-club-p4-instructions', 'Club Notice for Beautiful Homes Club', 'Dear members, Maintaining old buildings is expensive, and some of them occupy land that could be used for modern housing. The government is therefore considering demolishing certain old buildings and replacing them with new apartment blocks. Please tell us whether you support this proposal, explain your reasons, and suggest how historically or culturally important buildings should be protected.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'dbebbb69a74cfad4e502ee6c06e3288840e7d48edf0c1d6b3e5d03fd19f1aab4'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-car-club-p4-instructions', 'Club Notice for Car Club', 'Dear members, A motoring programme will take place across Europe, and the Car Club has been invited to send two representatives: one main driver and one passenger who can also drive well when necessary. We need reliable members with strong driving skills, good teamwork, and travel experience. Please suggest suitable candidates or explain what qualities the club should consider when selecting them.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'ca385d8f68fb6eaf336659552166ce33e22a6f475e90f51a73afaf556d49f17a'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-travel-club-p4-instructions', 'Club Notice for Travel Club', 'Dear members, The Travel Club is planning a campaign to encourage more tourists to visit our local area. At the same time, we want visitors to respect local people, traditions, and the environment. Please suggest ways to promote the area, explain what polite tourist behaviour should include, and recommend how we can communicate these messages clearly to visitors.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '0388fc4508e00179e049f8748faf5d58ff46fc97f63b8622fbca1e8b6403296a'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-movie-club-p4-instructions', 'Club Notice for Movie Club', 'Dear members, The Movie Club’s usual meeting room will be closed for repairs for the next several weeks. As a result, we need to find another place to meet or organise a different activity until the work is completed. Please suggest a suitable venue, an online option, or an alternative film-related activity that members could enjoy together.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '6ea67cc9416d78e7f9328136c9f26e1977be17cfbd4694619c8bec7093cd3abc'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-music-club-p4-instructions', 'Club Notice for Music Club', 'Dear members, The Music Club is planning a special event for people who enjoy listening to and performing music. We would like the event to welcome members of all ages, including both young people and older adults. Please share your ideas about suitable music, activities, facilities, and ways to make everyone feel comfortable and included.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '253106dfa5a4d559c6d86003c71f2f305f711b06b7eb387a63769ca791c6379b'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-college-club-p4-instructions', 'Club Notice for College Club', 'Dear members, We regret to inform you that the end-of-course examinations will take place two weeks earlier than originally planned. The examination scheduled for the 21st of next month will now be held on the 7th. We understand that this change may cause difficulties. Please share your concerns and suggest what support or alternative arrangements the college should provide.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '71b531090512548e8e4a1170e6241aca2e356bd644290ecd40b6a0e9797bf128'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-nature-club-version-2-p4-instructions', 'Club Notice for Nature Club (Version 2)', 'Dear members, This year, the Nature Club is planning a campaign to help children become more interested in nature and the natural world. Many children currently prefer staying indoors and playing computer games. Please suggest enjoyable ways to encourage them to explore outdoors, and recommend the best channels, messages, or activities for communicating the campaign to young people and their families.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'd3aa10af1a525ded48b592137b527be8926b71cdfa55b02ed2936cbab0b24f45'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-cooking-club-p4-instructions', 'Club Notice for Cooking Club', 'Dear members, All Cooking Club classes next week have been cancelled because the instructor will be on holiday. Replacement dates have not yet been confirmed, and the club has said that participants will not receive a refund. We understand that members may be disappointed. Please tell us how you feel and suggest a fair solution or alternative activity.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '6d249ba8f431677150e42faea50c84f44684559b259ccb5a41dfd5e868ce96aa'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-fitness-club-set002-p4-instructions', 'Club Notice for Fitness Club', 'Dear members, To reduce operating costs, the Fitness Club is considering limiting the amount of equipment available to members. Some members have also suggested closing the fitness shop and café. These changes could save money but may reduce the quality of the club experience. Please share your opinion and suggest other ways to cut costs without seriously affecting members.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '6a775dc609eb1e12f88fbdc2e719204e9e9b2939825fc8207afac111c850a709'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-technology-club-set002-p4-instructions', 'Club Notice for Technology Club', 'Dear members, The Technology Club will hold a public technology fair next month and is looking for volunteers to help organise the event. Volunteers may welcome visitors, explain displays, support speakers, and assist with technical problems. Please explain why technology is important, describe the skills and experience a good volunteer should have, and tell us why you would be suitable for the role.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '6c8e597e67d6b331a69b6514d12b01c325cdd8e15489a01b128f5e3d9addf38a'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-walking-club-version-2-p4-instructions', 'Club Notice for Walking Club (Version 2)', 'Dear members, Several Walking Club members have been using their phones while walking and are not paying enough attention to roads, traffic, or other people. This behaviour can cause accidents and makes group walks less enjoyable. Please share your opinion and suggest practical rules, reminders, or activities that could encourage members to walk safely and interact more with the group.', NULL, '{"instructions_type":"club_notice"}'::jsonb, 'e382717ea33b4587c43d9fdc12f10a290e6cadb4b8a12d893ce8b61b0bab1f62'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-food-club-version-2-p4-instructions', 'Club Notice for Food Club (Version 2)', 'Dear members, The Food Club is planning a special meeting with a well-known chef, and we hope to attract a large audience. The chef will give a talk and demonstrate how to prepare a meal. Please suggest an interesting topic for the talk, a suitable dish for the demonstration, and any additional activities that could make the event more enjoyable.', NULL, '{"instructions_type":"club_notice"}'::jsonb, '7a41ba4cfe1525095e5bbead85d4ee160dd56a13769594a3b011a558a8a00bb5'),
  ('writing'::public.aptis_skill_enum, 'instructions', 'writing-fashion-club-version-2-p4-instructions', 'Club Notice for Fashion Club (Version 2)', 'Dear members, Our Fashion Club is planning a special fashion event next month, and we would like to hear your views. We are considering two options. The first is an online fashion event, where members can watch presentations, meet designers online and ask questions from home. The second option is a live event with a fashion show, where members can meet in person, see new clothes and designs, and take part in other fashion activities. Please tell us which option you prefer and explain why. We would also like to hear any suggestions you have for making the event interesting and enjoyable. Fashion Club Manager', NULL, '{"instructions_type":"club_notice"}'::jsonb, '10efdcb10610b08ccf27f57d7601dad72efdf6e4059dd37b7b415c5108a56b8e')
ON CONFLICT (skill, source_key) DO UPDATE SET
  title = EXCLUDED.title,
