  content_hash = EXCLUDED.content_hash
WHERE aptis_content_blocks.title IS DISTINCT FROM EXCLUDED.title
   OR aptis_content_blocks.content IS DISTINCT FROM EXCLUDED.content
   OR aptis_content_blocks.media_url IS DISTINCT FROM EXCLUDED.media_url
   OR aptis_content_blocks.metadata IS DISTINCT FROM EXCLUDED.metadata
   OR aptis_content_blocks.content_hash IS DISTINCT FROM EXCLUDED.content_hash;

