  ('writing'::public.aptis_skill_enum, 1, 'text_input', 'writing-community-club-p1-q005', 'docs/05-writing.md', 'Where do you like to go in the summer?', 5, '{"input_type":"textarea","word_counter":true,"autosave":true,"submit_individually":true,"submit_with_club":true}'::jsonb, '{"club_key":"writing-club-community-club","topic":"Community Club","task_type":"short_answer","min_words":1,"max_words":5,"tone":null,"recipient_type":null,"source_section":"part_1"}'::jsonb, '5ea199d7a6e8f1065b7d61ad1241ce2cc3012079a6b79ff1e1066adcf6b7ff59'),
